css:
.cloudarch-sim-container {
    padding: 28px;
    background: linear-gradient(160deg, #05070f 0%, #0a1a33 55%, #081126 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e6ecf5;
}

.cloudarch-sim-container h1,
.cloudarch-sim-container h3 {
    color: #e6ecf5;
    margin: 0;
}

.cloudarch-sim-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;
    padding: 24px 28px;
    margin-bottom: 24px;
    background: linear-gradient(135deg, rgba(13,110,253,0.12), rgba(0,191,255,0.05));
    border: 1px solid rgba(0,191,255,0.22);
    border-radius: 14px;
    box-shadow: 0 0 24px rgba(0,191,255,0.08);
}

.cloudarch-sim-header-brand {
    display: flex;
    align-items: center;
    gap: 16px;
}

.cloudarch-sim-brand-mark {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 56px;
    height: 56px;
    border-radius: 12px;
    background: linear-gradient(135deg, #0d6efd, #00bfff);
    color: #05070f;
    font-weight: 800;
    font-size: 1.3rem;
    letter-spacing: 0.08em;
    box-shadow: 0 6px 18px rgba(13,110,253,0.35);
}

.cloudarch-sim-header h1 {
    font-size: 1.35rem;
    letter-spacing: 0.04em;
    color: #f5f9ff;
}

.cloudarch-sim-header-sub {
    color: #8fa5c4;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-top: 4px;
}

.cloudarch-sim-period-counter {
    background: rgba(0,191,255,0.12);
    border: 1px solid rgba(0,191,255,0.3);
    color: #9fe5ff;
    padding: 10px 18px;
    border-radius: 999px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-size: 0.85rem;
}

.cloudarch-sim-period-counter span {
    margin: 0 3px;
}

.cloudarch-sim-briefing {
    background: rgba(15,23,42,0.75);
    border: 1px solid rgba(122,162,255,0.22);
    border-radius: 14px;
    padding: 22px 26px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}

.cloudarch-sim-briefing::before {
    content: '';
    position: absolute;
    top: 0; left: 0; bottom: 0;
    width: 4px;
    background: linear-gradient(180deg, #00bfff, #0d6efd);
}

.cloudarch-sim-briefing-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
}

.cloudarch-sim-briefing-label {
    color: #00bfff;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    font-weight: 700;
}

.cloudarch-sim-briefing-round {
    background: rgba(0,191,255,0.15);
    color: #9fe5ff;
    padding: 4px 12px;
    border-radius: 6px;
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.08em;
}

.cloudarch-sim-briefing-text {
    color: #cdd9ec;
    font-size: 0.95rem;
    line-height: 1.6;
}

.cloudarch-sim-briefing-text strong {
    color: #ffd466;
}

.cloudarch-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}

.cloudarch-sim-kpi-card {
    background: linear-gradient(180deg, rgba(17,27,48,0.95), rgba(12,20,37,0.95));
    border: 1px solid rgba(122,162,255,0.18);
    border-radius: 12px;
    padding: 18px 18px;
    position: relative;
    overflow: hidden;
    transition: transform 0.2s ease, border-color 0.2s ease;
}

.cloudarch-sim-kpi-card:hover {
    transform: translateY(-2px);
    border-color: rgba(0,191,255,0.45);
}

.cloudarch-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #0d6efd, #00bfff);
}

.cloudarch-sim-kpi-budget::before { background: linear-gradient(90deg, #ffd466, #ff8a3c); }
.cloudarch-sim-kpi-uptime::before { background: linear-gradient(90deg, #00ff88, #00bfff); }
.cloudarch-sim-kpi-compliance::before { background: linear-gradient(90deg, #a78bfa, #60a5fa); }
.cloudarch-sim-kpi-security::before { background: linear-gradient(90deg, #ff6b6b, #ffd466); }
.cloudarch-sim-kpi-board::before { background: linear-gradient(90deg, #f472b6, #a78bfa); }
.cloudarch-sim-kpi-delivery::before { background: linear-gradient(90deg, #34d399, #60a5fa); }

.cloudarch-sim-kpi-label {
    color: #8fa5c4;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-weight: 700;
    margin-bottom: 8px;
}

.cloudarch-sim-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #f5f9ff;
    line-height: 1.1;
}

.cloudarch-sim-kpi-sub {
    color: #6c7e97;
    font-size: 0.72rem;
    margin-top: 6px;
    letter-spacing: 0.02em;
}

.cloudarch-sim-controls {
    background: rgba(10,18,34,0.85);
    border: 1px solid rgba(122,162,255,0.18);
    border-radius: 14px;
    padding: 26px;
    margin-bottom: 24px;
}

.cloudarch-sim-controls h3 {
    color: #00bfff;
    font-size: 1rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin-bottom: 20px;
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(122,162,255,0.15);
}

.cloudarch-sim-panel {
    margin-bottom: 18px;
    padding: 16px 18px;
    background: rgba(8,15,30,0.6);
    border: 1px solid rgba(122,162,255,0.12);
    border-radius: 10px;
    display: none;
}

.cloudarch-sim-panel.active {
    display: block;
    animation: cloudarchFadeIn 0.3s ease;
}

@keyframes cloudarchFadeIn {
    from { opacity: 0; transform: translateY(4px); }
    to { opacity: 1; transform: translateY(0); }
}

.cloudarch-sim-controls label {
    display: block;
    color: #9fb4d1;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin: 10px 0 6px;
    font-weight: 600;
}

.cloudarch-sim-controls select,
.cloudarch-sim-controls input[type="number"],
.cloudarch-sim-controls input[type="text"] {
    width: 100%;
    background: #0a1428;
    border: 1px solid #1f2f50;
    color: #e6ecf5;
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.95rem;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.cloudarch-sim-controls select:focus,
.cloudarch-sim-controls input:focus {
    outline: none;
    border-color: #00bfff;
    box-shadow: 0 0 0 3px rgba(0,191,255,0.18);
}

.cloudarch-sim-controls select option {
    background: #0a1428;
    color: #e6ecf5;
}

.cloudarch-sim-actions {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    margin-top: 16px;
}

.cloudarch-sim-actions .btn-primary {
    background: linear-gradient(135deg, #0d6efd, #00bfff);
    border: none;
    color: #05070f;
    font-weight: 700;
    letter-spacing: 0.05em;
    padding: 12px 24px;
    border-radius: 8px;
    box-shadow: 0 6px 18px rgba(13,110,253,0.35);
    transition: transform 0.15s ease, box-shadow 0.2s ease;
}

.cloudarch-sim-actions .btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 8px 22px rgba(13,110,253,0.5);
}

.cloudarch-sim-actions .btn-outline-secondary {
    background: transparent;
    border: 1px solid rgba(122,162,255,0.3);
    color: #9fb4d1;
    padding: 10px 18px;
    border-radius: 8px;
}

.cloudarch-sim-actions .btn-outline-secondary:hover {
    background: rgba(122,162,255,0.12);
    color: #e6ecf5;
}

.cloudarch-sim-hint {
    display: none;
    background: rgba(255,212,102,0.1);
    border: 1px solid rgba(255,212,102,0.35);
    color: #ffd466;
    padding: 14px 18px;
    border-radius: 10px;
    margin-bottom: 24px;
    font-size: 0.92rem;
    line-height: 1.5;
}

.cloudarch-sim-hint.visible {
    display: block;
}

.cloudarch-sim-chart-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 24px;
}

.cloudarch-sim-chart-card {
    background: rgba(10,18,34,0.85);
    border: 1px solid rgba(122,162,255,0.18);
    border-radius: 12px;
    padding: 18px;
    height: 280px;
}

.cloudarch-sim-chart-card canvas {
    max-height: 240px;
}

.cloudarch-sim-history {
    background: rgba(10,18,34,0.85);
    border: 1px solid rgba(122,162,255,0.18);
    border-radius: 12px;
    padding: 22px 26px;
    margin-bottom: 32px;
}

.cloudarch-sim-history h3 {
    color: #00bfff;
    font-size: 1rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    margin-bottom: 14px;
}

.cloudarch-sim-history table {
    width: 100%;
    color: #cdd9ec;
    font-size: 0.88rem;
}

.cloudarch-sim-history table thead th {
    color: #00bfff;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
    border-bottom: 1px solid rgba(122,162,255,0.25);
    padding: 10px 8px;
    background: transparent;
}

.cloudarch-sim-history table tbody tr {
    border-bottom: 1px solid rgba(122,162,255,0.08);
}

.cloudarch-sim-history table tbody td {
    padding: 10px 8px;
    background: transparent;
    color: #cdd9ec;
    border: none;
}

@media (max-width: 768px) {
    .cloudarch-sim-container { padding: 14px; }
    .cloudarch-sim-header { flex-direction: column; align-items: flex-start; }
    .cloudarch-sim-chart-row { grid-template-columns: 1fr; }
    .cloudarch-sim-kpi-value { font-size: 1.5rem; }
}

/* ---- Completion message (v1.1.0, namespaced .ca-cm-*) ---- */
.ca-cm { padding:24px; border-radius:14px; background:#0e1b2b; color:#e6edf5; border:1px solid rgba(88,166,255,0.28); }
.ca-cm-scorewrap { display:flex; align-items:baseline; gap:14px; }
.ca-cm-score { font-size:56px; font-weight:800; color:#58a6ff; line-height:1; }
.ca-cm-score span { font-size:22px; color:#8cc0ff; font-weight:600; }
.ca-cm-grade { font-size:34px; font-weight:800; color:#8cc0ff; margin-left:auto; padding:4px 16px; border:2px solid #58a6ff; border-radius:12px; }
.ca-cm-verdict { margin-top:8px; font-size:22px; font-weight:700; color:#fff; }
.ca-cm-tier-exemplary .ca-cm-verdict { color:#2ecc71; }
.ca-cm-tier-strong .ca-cm-verdict { color:#58a6ff; }
.ca-cm-tier-adequate .ca-cm-verdict { color:#f39c12; }
.ca-cm-tier-needs .ca-cm-verdict { color:#e74c3c; }
.ca-cm-kpis { display:flex; flex-wrap:wrap; gap:12px; margin:18px 0; }
.ca-cm-kpi { flex:1 1 120px; background:rgba(88,166,255,0.1); border:1px solid rgba(88,166,255,0.22); border-radius:10px; padding:12px; text-align:center; }
.ca-cm-kpi-val { display:block; font-size:18px; font-weight:700; color:#8cc0ff; }
.ca-cm-kpi-lbl { display:block; font-size:12px; color:#9fb3c8; margin-top:4px; }
.ca-cm-insights-h { font-size:16px; font-weight:700; color:#8cc0ff; margin-top:8px; }
.ca-cm-insights { margin:8px 0 0; padding-left:20px; }
.ca-cm-insights li { margin:4px 0; line-height:1.4; }

