        getHint(state, results) {
            if (!results) return null;
            if (results.fines && results.fines >= 1) return window.mySimulation.t('hint_fine');
            if (state.domainState.itBudget > 28) return window.mySimulation.t('hint_budget_high');
            if (state.domainState.uptime < 99.8) return window.mySimulation.t('hint_uptime_low');
            if (state.domainState.compliance < 60) return window.mySimulation.t('hint_compliance_low');
            if (state.domainState.boardConfidence < 50) return window.mySimulation.t('hint_board_low');
