        _t(key, fallback) {
            try { var v = window.mySimulation.t(key); if (v && v !== key) return v; } catch (e) {}
            if (fallback !== undefined) return fallback;
            if (!this._enT) { try { this._enT = this.getTranslations().en || {}; } catch (e) { this._enT = {}; } }
            return (this._enT[key] != null) ? this._enT[key] : key;
        }

        // Composite 0-100 (single source of truth; same bands the sim already used ->
        // score-neutral) now PERSISTED so the server can read a grade (was 0.0 before).
        _composite(m) {
            var finalBudget = (m.itBudget !== undefined) ? m.itBudget : 28;
            var costReduction = ((28 - finalBudget) / 28) * 100;
            var uptime = (m.uptime !== undefined) ? m.uptime : 99.5;
            var compliance = (m.compliance !== undefined) ? m.compliance : 70;
            var boardConfidence = (m.boardConfidence !== undefined) ? m.boardConfidence : 65;
            var fines = m.cumulativeFines || 0;
            var sc = 0;
            if (costReduction >= 20) sc += 25; else if (costReduction >= 15) sc += 15; else if (costReduction >= 10) sc += 10;
            if (uptime >= 99.99) sc += 20; else if (uptime >= 99.95) sc += 15; else if (uptime >= 99.90) sc += 10;
            if (fines === 0) sc += 20; else if (fines < 1) sc += 10;
            if (compliance >= 85) sc += 15; else if (compliance >= 70) sc += 8;
            if (boardConfidence >= 80) sc += 15; else if (boardConfidence >= 60) sc += 8;
            sc = Math.max(0, Math.min(100, Math.round(sc)));
            var tier = 'needs', grade = 'D';
            if (sc >= 80) { tier = 'exemplary'; grade = 'A'; }
            else if (sc >= 60) { tier = 'strong'; grade = 'B'; }
            else if (sc >= 40) { tier = 'adequate'; grade = 'C'; }
            return { score: sc, tier: tier, grade: grade, costReduction: costReduction };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1].results || {};
            var ds = history[history.length - 1].domainState || {};
            var finalBudget = last.itBudget || 28;
            var costReduction = ((28 - finalBudget) / 28) * 100;
            var uptime = last.uptime || 99.5;
            var compliance = last.compliance || 70;
            var boardConfidence = last.boardConfidence || 65;
            var fines = (last.cumulativeFines !== undefined) ? last.cumulativeFines : (ds.cumulativeFines || 0);

            var __c = this._composite({ itBudget: finalBudget, uptime: uptime, compliance: compliance, boardConfidence: boardConfidence, cumulativeFines: fines });
            var T = this._t.bind(this);
            var cr = costReduction.toFixed(1);
            var insights = [];
            if (costReduction >= 20) insights.push(T('ins_cost_met').replace('{x}', cr));
            else insights.push(T('ins_cost_short').replace('{x}', cr));
            if (uptime >= 99.99) insights.push(T('ins_uptime_five'));
            if (fines > 0) insights.push(T('ins_fines').replace('{x}', '$' + fines.toFixed(2) + 'M'));
            if (boardConfidence < 60) insights.push(T('ins_board_low'));

            return {
                totalCostReduction: Number(costReduction.toFixed(1)),
                finalBudget: finalBudget,
                finalUptime: uptime,
                totalFines: fines,
                boardConfidence: boardConfidence,
                performance: __c.tier,
                performanceLabel: T('verdict_' + __c.tier),
                grade: __c.grade,
                score: __c.score,
                overallScore: __c.score,
                composite: __c.score,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = this._t.bind(this);
            if (!summary || summary.score === undefined) return '<div class="ca-cm"><p>' + T('cm_no_data', 'Simulation complete.') + '</p></div>';
            var tier = summary.performance || 'needs';
            var label = summary.performanceLabel || T('verdict_' + tier);
            var chips = (summary.insights && summary.insights.length) ? summary.insights.map(function(x){ return '<li>' + x + '</li>'; }).join('') : '<li>' + T('cm_no_insights', 'No standout insights this run.') + '</li>';
            var kpi = function(k, fb, val){ return '<div class="ca-cm-kpi"><span class="ca-cm-kpi-val">' + val + '</span><span class="ca-cm-kpi-lbl">' + T(k, fb) + '</span></div>'; };
            return '' +
              '<div class="ca-cm ca-cm-tier-' + tier + '">' +
                '<div class="ca-cm-scorewrap"><div class="ca-cm-score">' + summary.score + '<span>/100</span></div><div class="ca-cm-grade">' + (summary.grade || '') + '</div></div>' +
                '<div class="ca-cm-verdict">' + label + '</div>' +
                '<div class="ca-cm-kpis">' +
                  kpi('cm_kpi_cost', 'Cost Reduction', summary.totalCostReduction + '%') +
                  kpi('cm_kpi_uptime', 'Uptime', Number(summary.finalUptime).toFixed(2) + '%') +
                  kpi('cm_kpi_board', 'Board Confidence', Math.round(summary.boardConfidence) + '%') +
                  kpi('cm_kpi_fines', 'Regulatory Fines', '$' + Number(summary.totalFines).toFixed(2) + 'M') +
                '</div>' +
                '<div class="ca-cm-insights-h">' + T('cm_insights_heading', 'Key Insights') + '</div>' +
                '<ul class="ca-cm-insights">' + chips + '</ul>' +
              '</div>';
        }

